commands.command:
$ErrorActionPreference='Stop'
$taskRoot='<WORKTREE>'
$taskRun=[guid]::NewGuid().ToString('N').Substring(0,12)
$taskContainer='schoolpilot-heartbeat-native-'+$taskRun
$taskDb='schoolpilot_redesign_heartbeat_'+$taskRun
$taskEvidence=Join-Path $env:TEMP ('release297-heartbeat-native-'+$taskRun)
$taskPassword=[guid]::NewGuid().ToString('N')
New-Item -ItemType Directory -Path $taskEvidence | Out-Null
$taskCreated=$false
$taskResult=1
try {
 npm run build *> (Join-Path $taskEvidence 'build.log')
 if ($LASTEXITCODE -ne 0) {throw 'Backend build failed'}
 docker exec schoolpilot-db pg_dump -U schoolpilot -d schoolpilot_redesign_usage_20260930 --schema-only --no-owner --no-privileges | Set-Content -LiteralPath (Join-Path $taskEvidence 'schema.sql') -Encoding utf8
 if ($LASTEXITCODE -ne 0) {throw 'Read-only fixture schema export failed'}
 $taskImage=(docker inspect schoolpilot-db --format '{{.Image}}').Trim()
 if ($taskImage -cnotmatch '^sha256:[a-f0-9]{64}$') {throw 'Image identity invalid'}
 docker run --detach --name $taskContainer --label "codex.heartbeat-native=$taskRun" --cpus 4 --memory 4g --memory-swap 4g --publish '127.0.0.1::5432' --env "POSTGRES_DB=$taskDb" --env 'POSTGRES_USER=native_owner' --env "POSTGRES_PASSWORD=$taskPassword" $taskImage *> (Join-Path $taskEvidence 'container.log')
 $taskLabels=docker inspect $taskContainer --format '{{json .Config.Labels}}' | ConvertFrom-Json
 if ($taskLabels.'codex.heartbeat-native' -cne $taskRun) {throw 'Owned fixture creation failed'}
 $taskCreated=$true
 $taskPorts=docker inspect $taskContainer --format '{{json .NetworkSettings.Ports}}' | ConvertFrom-Json
 if ($taskPorts.'5432/tcp'[0].HostIp -cne '127.0.0.1') {throw 'Fixture port is not loopback-only'}
 $taskPort=$taskPorts.'5432/tcp'[0].HostPort
 $taskReady=$false
 for ($taskAttempt=0;$taskAttempt -lt 30;$taskAttempt++) {
  docker exec $taskContainer pg_isready -h 127.0.0.1 -U native_owner -d $taskDb *> $null
  if ($LASTEXITCODE -eq 0) {$taskReady=$true;break}
  Start-Sleep -Milliseconds 500
 }
 if (-not $taskReady) {throw 'Fixture readiness failed'}
 Get-Content -LiteralPath (Join-Path $taskEvidence 'schema.sql') -Raw | docker exec -i $taskContainer psql -U native_owner -d $taskDb -v ON_ERROR_STOP=1 *> (Join-Path $taskEvidence 'schema-restore.log')
 if ($LASTEXITCODE -ne 0) {throw 'Fixture schema restore failed'}
 $env:DATABASE_URL="<REDACTED_CREDENTIAL_URL>"
 $env:DATABASE_URL_PRIVILEGED=$env:DATABASE_URL
 $env:JWT_SECRET=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N')
 $env:SESSION_SECRET=$env:JWT_SECRET
 $env:STUDENT_TOKEN_SECRET=$env:JWT_SECRET
 $env:NODE_ENV='test';$env:REDIS_URL='';$env:SCHEDULER_ENABLED='false';$env:RLS_GUC_ENABLED='true'
 $taskRegistry=Get-Content src/config/rlsRegistry.json -Raw | ConvertFrom-Json
 $env:RLS_ENABLED_TABLES=$taskRegistry.inventories.classpilotPrivateChatLifecyclePostExpand.tables -join ','
 $env:RUN_LEGACY_MIGRATIONS_ONLY='true';$env:RUN_MIGRATIONS_ONLY='false'
 node dist/index.js *> (Join-Path $taskEvidence 'legacy.log')
 if ($LASTEXITCODE -ne 0) {throw 'Fixture legacy convergence failed'}
 $env:RUN_LEGACY_MIGRATIONS_ONLY='false';$env:RUN_MIGRATIONS_ONLY='true'
 node dist/index.js *> (Join-Path $taskEvidence 'versioned.log')
 if ($LASTEXITCODE -ne 0) {throw 'Fixture versioned convergence failed'}
 $env:RUN_MIGRATIONS_ONLY='false'
 node --import ./tests/test-environment.mjs --import tsx --test --test-concurrency=1 tests/classpilot-heartbeat-presence.test.ts tests/classpilot-screenshot-publish-gate.test.ts tests/classpilot-student-session-recovery.integration.test.ts *> (Join-Path $taskEvidence 'tests.log')
 $taskResult=$LASTEXITCODE
 Get-Content -LiteralPath (Join-Path $taskEvidence 'tests.log') -Tail 15
} catch { Write-Output $_.Exception.Message } finally {
 if ($taskCreated) {
  $taskLabels=docker inspect $taskContainer --format '{{json .Config.Labels}}' | ConvertFrom-Json
  if ($taskLabels.'codex.heartbeat-native' -cne $taskRun -or $taskContainer -cne ('schoolpilot-heartbeat-native-'+$taskRun)) {throw 'Refuse unowned cleanup'}
  docker rm --force --volumes $taskContainer *> (Join-Path $taskEvidence 'cleanup.log')
 }
 [ordered]@{exitCode=$taskResult;evidenceDirectory=$taskEvidence;productionMutations=0;isolatedContainer=$taskContainer;restrictedRoleProof=$false;sourceStatus='working-tree not frozen';generatedContainerRemoved=$taskCreated} | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $taskEvidence 'result.json') -Encoding utf8
 Write-Output ('Evidence: '+$taskEvidence)
}
exit $taskResult

